46	DelayEstimatorManager& GetDelayEstimatorManagerSingleton() {
47	  static absl::NoDestructor<DelayEstimatorManager> manager;
48	  return *manager;
49	}
50	
51	absl::StatusOr<DelayEstimator*> DelayEstimatorManager::GetDelayEstimator(
52	    std::string_view name) const {
53	  if (!estimators_.contains(name)) {
54	    if (estimator_names_.empty()) {
55	      return absl::NotFoundError(absl::StrFormat(
56	          R"TXT(No delay estimator found named "%s".
57	
58	No estimators are registered.
59	
60	This can be caused by a few different issues.
61	
62	1) Was InitXls called?
63	
64	   This needs be called early during binary startup or before running other xls
65	   code.
66	
67	2) Were estimators linked into the binary?
68	
69	   Estimators need to be linked in order to be available. The standard
70	   estimators are linked from '//xls/estimators/delay_model/models'
71	   and are also exported as '//xls/estimators' and
72	   '//xls/public:passes_and_estimators'. At least one of these must
73	   be in the 'deps' tree to ensure that estimators are available.)TXT",
74	          name));
75	    }
76	    return absl::NotFoundError(absl::StrFormat(
77	        R"TXT(No delay estimator found named \"%s\".
78	
79	Available estimators: %s
80	
81	It is possible you didn't link the estimator into the binary.
82	
83	Do you have '//xls/estimators/delay_model/models' in your dep tree?
84	
85	Is the estimator library a dependency of '//.../models'?)TXT",
86	        name, absl::StrJoin(estimator_names_, ", ")));
87	  }
88	  return estimators_.at(name).second.get();
89	}
90	
91	absl::StatusOr<DelayEstimator*>
92	DelayEstimatorManager::GetDefaultDelayEstimator() const {
93	  if (estimators_.empty()) {
94	    return absl::NotFoundError(
95	        "No delay estimator has been registered. Did the build "
96	        "target forget to link a plugin?");
97	  }
98	  int highest_precedence = 0;
99	  DelayEstimator* highest = nullptr;
100	  for (const std::string& name : estimator_names_) {
101	    const std::pair<DelayEstimatorPrecedence, std::unique_ptr<DelayEstimator>>&
102	        pair = estimators_.at(name);
103	    DelayEstimatorPrecedence precedence = pair.first;
104	    int precedence_value = static_cast<int>(precedence);
105	    if (precedence_value > highest_precedence) {
106	      highest_precedence = precedence_value;
107	      highest = pair.second.get();
108	    }
109	  }
110	  return highest;
111	}
112	
113	absl::Status DelayEstimatorManager::RegisterDelayEstimator(
114	    std::unique_ptr<DelayEstimator> delay_estimator,
115	    DelayEstimatorPrecedence precedence) {
116	  std::string name = delay_estimator->name();
117	  if (estimators_.contains(name)) {
118	    return absl::InternalError(
119	        absl::StrFormat("Delay estimator named %s already exists", name));
120	  }
121	  estimators_[name] = {precedence, std::move(delay_estimator)};
122	  estimator_names_.push_back(name);
123	  std::sort(estimator_names_.begin(), estimator_names_.end());
124	
125	  return absl::OkStatus();
126	}
