130	// TODO(leary): 2019-08-19 Read all of the curve-fit values from a
131	// characterization file for easier reference / recomputing if necessary.
132	/* static */ absl::StatusOr<int64_t> GetLogicalEffortDelayInTau(Node* node) {
133	  auto get_linear_logical_effort_for_n_operands =
134	      [](int64_t operand_count, netlist::CellKind kind,
135	         bool invert) -> absl::StatusOr<int64_t> {
136	    XLS_ASSIGN_OR_RETURN(
137	        double base_effort,
138	        netlist::logical_effort::GetLogicalEffort(kind, operand_count));
139	    return std::ceil(invert ? base_effort + int64_t{1} : base_effort);
140	  };
141	  auto get_logical_effort = [node](netlist::CellKind kind,
142	                                   bool invert) -> absl::StatusOr<int64_t> {
143	    XLS_ASSIGN_OR_RETURN(double base_effort,
144	                         netlist::logical_effort::GetLogicalEffort(
145	                             kind, node->operands().size()));
146	    return std::ceil(invert ? base_effort + int64_t{1} : base_effort);
147	  };
148	  // Calculate the reduction logical effort. We use the lower of a binary-tree
149	  // reduction and a linear reduction.
150	  //
151	  // TODO(allight): A binary tree is not actually always the best architecture
152	  // for a reduction and the correspondence between effort and delay is not
153	  // always simple. For now a binary-tree is a good approximation however. See
154	  // chapter 11 of "Sutherland, I., et al., Logical Effort: Designing Fast CMOS
155	  // Circuits" (and frankly the rest of the book) for more information. For a
156	  // follow up we can find the optimal branching factors and use them. See
157	  // chapter 11.2 for more information.
158	  auto get_reduction_logical_effort_of =
159	      [](netlist::CellKind kind, bool invert,
160	         int64_t bit_count) -> absl::StatusOr<int64_t> {
161	    if (bit_count < 2) {
162	      return 0;
163	    }
164	    XLS_ASSIGN_OR_RETURN(
165	        double base_effort,
166	        netlist::logical_effort::GetLogicalEffort(kind, bit_count));
167	    int64_t effort_raw =
168	        std::ceil(invert ? base_effort + int64_t{1} : base_effort);
169	    uint64_t tree_depth = CeilOfLog2(bit_count);
170	    XLS_ASSIGN_OR_RETURN(double base_bin_tree_effort,
171	                         netlist::logical_effort::GetLogicalEffort(kind, 2));
172	    int64_t tree_node_effort_raw = std::ceil(
173	        invert ? base_bin_tree_effort + int64_t{1} : base_bin_tree_effort);
174	    int64_t effort_tree = tree_node_effort_raw * tree_depth;
175	    return std::min(effort_raw, effort_tree);
176	  };
177	  auto get_reduction_logical_effort =
178	      [&](netlist::CellKind kind, bool invert) -> absl::StatusOr<int64_t> {
179	    const int64_t bit_count = node->operand(0)->BitCountOrDie();
180	    return get_reduction_logical_effort_of(kind, invert, bit_count);
181	  };
182	  switch (node->op()) {
183	    // TODO(leary): 2019-09-24 Collect real numbers for these.
184	    case Op::kGate:
185	      return get_logical_effort(netlist::CellKind::kNand, /*invert=*/true);
186	    // TODO(allight): The nary ops (And, Nand, Nor, Or, Xor) should all be
187	    // modeled using a tree structure too. Note that the current tree
188	    // implementation won't work with nand/nor since they are not associative
189	    // and care will need to be taken to ensure they are modeled accurately.
190	    // Currently this models it as though a single cell is always used but this
191	    // is simply not true (especially as the synthesizer trades off area and
192	    // delay).
193	    case Op::kAnd:
194	      return get_logical_effort(netlist::CellKind::kNand, /*invert=*/true);
195	    case Op::kNand:
196	      return get_logical_effort(netlist::CellKind::kNand, /*invert=*/false);
197	    case Op::kNor:
198	      return get_logical_effort(netlist::CellKind::kNor, /*invert=*/false);
199	    case Op::kOr:
200	      return get_logical_effort(netlist::CellKind::kNor, /*invert=*/true);
201	    case Op::kXor:
202	      return get_logical_effort(netlist::CellKind::kXor, /*invert=*/false);
203	    case Op::kNot:
204	      return get_logical_effort(netlist::CellKind::kInverter, /*invert=*/false);
205	    // NB By modeling the reduction ops as a binary tree we are assuming the
206	    // synthsizer takes the area/delay tradeoff inherent in which cells it
207	    // chooses in a particular direction. This choice is likely not the optimal
208	    // one for either area or delay in real process nodes however it is a
209	    // reasonable approximation.
210	    case Op::kAndReduce:
211	      return get_reduction_logical_effort(netlist::CellKind::kNand,
212	                                          /*invert=*/true);
213	    case Op::kOrReduce:
214	      return get_reduction_logical_effort(netlist::CellKind::kNor,
215	                                          /*invert=*/true);
216	    case Op::kXorReduce:
217	      return get_reduction_logical_effort(netlist::CellKind::kXor,
218	                                          /*invert=*/false);
219	    case Op::kEncode: {
220	      // Each output bit is the OR reduction of half of the input
221	      // bits. Equivalently the NOR reduction delay plus an inverter delay.
222	      // TODO(meheff): Characterize this properly.
223	      int64_t operand_width = node->operand(0)->BitCountOrDie();
224	      if (operand_width <= 2) {
225	        // A 2-bit or less encode simply passes through the MSB.
226	        return 0;
227	      }
228	      int64_t bit_count = (operand_width + 1) / 2;
229	      XLS_ASSIGN_OR_RETURN(int64_t nor_delay, get_reduction_logical_effort_of(
230	                                                  netlist::CellKind::kNor,
231	                                                  /*invert=*/true,
232	                                                  /*bit_count=*/bit_count));
233	      // The last not isn't needed so remove it.
234	      return std::ceil(nor_delay - 1);
235	    }
236	    case Op::kOneHotSel: {
237	      // Each bit of the OHS can be computed in parallel without interference.
238	      // That means the delay of an N-bit OHS is equivalent to the delay of a
239	      // 1-bit OHS.
240	      //
241	      // We model the 1 bit OHS as an OR-reduce of an AND between a bit of the
242	      // selector and the corresponding case.
243	      OneHotSelect* ohs = node->As<OneHotSelect>();
244	      if (ohs->cases().empty()) {
245	        // How does this even happen? Anyway this is just a constant 0.
246	        return 0;
247	      }
248	
249	      if (ohs->selector()->Is<Literal>()) {
250	        // This should synthesize down to an OR of the selected inputs.
251	        int64_t selected_inputs =
252	            ohs->selector()->As<Literal>()->value().bits().PopCount();
253	        if (selected_inputs <= 1) {
254	          return 0;
255	        }
256	        XLS_ASSIGN_OR_RETURN(int64_t red, get_reduction_logical_effort_of(
257	                                              netlist::CellKind::kNor,
258	                                              /*invert=*/true,
259	                                              /*bit_count=*/selected_inputs));
260	        XLS_ASSIGN_OR_RETURN(
261	            int64_t nor,
262	            get_linear_logical_effort_for_n_operands(
263	                /*operand_count=*/selected_inputs, netlist::CellKind::kNor,
264	                /*invert=*/true));
265	        return std::min(red, nor);
266	      }
267	
268	      if (ohs->cases().size() == 1) {
269	        // This should just be an AND with the selector.
270	        return get_linear_logical_effort_for_n_operands(
271	            /*operand_count=*/2, netlist::CellKind::kNand,
272	            /*invert=*/true);
273	      }
274	
275	      // Can perform 1 bit OHS as
276	      //
277	      // Using de Morgan's Law:
278	      //
279	      //     OR(AND(C, X), AND(C, Y), ...) =
280	      //     NOT(AND(NOT(AND(C, X)), NOT(AND(C, Y)), ...)) =
281	      //     NAND(NAND(C, X), NAND(C, Y), ...)
282	      //
283	      // Inner Nand.
284	      XLS_ASSIGN_OR_RETURN(int64_t inner_nand_delay,
285	                           get_linear_logical_effort_for_n_operands(
286	                               2, netlist::CellKind::kNand, /*invert=*/false));
287	      // Outer nand
288	      // NB reduction_logical_effort_of returns the minimum of linear and tree
289	      // logical effort.
290	      XLS_ASSIGN_OR_RETURN(int64_t outer_nand_red,
291	                           get_reduction_logical_effort_of(
292	                               netlist::CellKind::kNand, /*invert=*/false,
293	                               /*bit_count=*/ohs->cases().size()));
294	      return outer_nand_red + inner_nand_delay;
295	    }
296	    default:
297	      break;
298	  }
299	  return absl::UnimplementedError(
300	      "Cannot compute delay of node using logical effort:" +
301	      node->ToStringWithOperandTypes());
302	}
303	
304	}  // namespace
