306	DecoratingDelayEstimator::DecoratingDelayEstimator(
307	    std::string_view name, const DelayEstimator& decorated,
308	    std::function<int64_t(Node*, int64_t)> modifier)
309	    : DelayEstimator(name),
310	      decorated_(decorated),
311	      modifier_(ABSL_DIE_IF_NULL(std::move(modifier))) {}
312	
313	absl::StatusOr<int64_t> DecoratingDelayEstimator::GetOperationDelayInPs(
314	    Node* node) const {
315	  XLS_ASSIGN_OR_RETURN(int64_t original,
316	                       decorated_.GetOperationDelayInPs(node));
317	  return modifier_(node, original);
318	}
319	
320	FirstMatchDelayEstimator::FirstMatchDelayEstimator(
321	    std::string_view name, std::vector<const DelayEstimator*> estimators)
322	    : DelayEstimator(name), estimators_(std::move(estimators)) {}
323	
324	absl::StatusOr<int64_t> FirstMatchDelayEstimator::GetOperationDelayInPs(
325	    Node* node) const {
326	  absl::StatusOr<int64_t> result;
327	  for (const DelayEstimator* estimator : estimators_) {
328	    result = estimator->GetOperationDelayInPs(node);
329	    if (result.ok()) {
330	      return result;
331	    }
332	  }
333	  return result;
334	}
335	
336	CachingDelayEstimator::CachingDelayEstimator(std::string_view name,
337	                                             const DelayEstimator& cached)
338	    : DelayEstimator(name), cached_(cached) {}
339	
340	absl::StatusOr<int64_t> CachingDelayEstimator::GetOperationDelayInPs(
341	    Node* node) const {
342	  if (ContainsNodeDelay(node)) {
343	    return GetNodeDelay(node);
344	  }
345	
346	  XLS_ASSIGN_OR_RETURN(int64_t delay, cached_.GetOperationDelayInPs(node));
347	  AddNodeDelay(node, delay);
348	  return delay;
349	}
350	
351	/* static */ absl::StatusOr<int64_t> DelayEstimator::GetLogicalEffortDelayInPs(
352	    Node* node, int64_t tau_in_ps) {
353	  XLS_ASSIGN_OR_RETURN(int64_t delay_in_tau, GetLogicalEffortDelayInTau(node));
354	  return delay_in_tau * tau_in_ps;
355	}
356	
357	absl::StatusOr<DelayAnnotator> DelayAnnotator::Create(
358	    FunctionBase* f, const DelayEstimator& delay_estimator) {
359	  absl::flat_hash_map<Node*, Entry> entries;
360	  XLS_ASSIGN_OR_RETURN(std::vector<Node*> topo_sort_nodes, TopoSort(f));
361	  for (Node* node : topo_sort_nodes) {
362	    int64_t max_path_delay = 0;
363	    for (Node* operand : node->operands()) {
364	      max_path_delay =
365	          std::max(max_path_delay, entries.at(operand).path_delay_ps);
366	    }
367	    XLS_ASSIGN_OR_RETURN(int64_t node_delay,
368	                         delay_estimator.GetOperationDelayInPs(node));
369	    entries[node] = {
370	        .node_delay_ps = node_delay,
371	        .path_delay_ps = max_path_delay + node_delay,
372	    };
373	  }
374	  return DelayAnnotator(std::move(entries));
375	}
376	
377	Annotation DelayAnnotator::NodeAnnotation(Node* node) const {
378	  auto it = entries_.find(node);
379	  if (it == entries_.end()) {
380	    return Annotation();
381	  }
382	  return Annotation{.suffix = absl::StrFormat("[%dps (+%dps)]",
383	                                              it->second.path_delay_ps,
384	                                              it->second.node_delay_ps)};
385	}
