298	// Returns the critical-path delay through each pipeline stage.
299	absl::StatusOr<std::vector<int64_t>> GetDelayPerStageInPs(
300	    FunctionBase* f, const PipelineSchedule& schedule,
301	    const DelayEstimator& delay_estimator) {
302	  std::vector<int64_t> delay_per_stage(schedule.length() + 1);
303	  // The delay from the beginning of the stage at which each node completes.
304	  absl::flat_hash_map<Node*, int64_t> completion_time;
305	  XLS_ASSIGN_OR_RETURN(std::vector<Node*> sorted_nodes, TopoSort(f));
306	  for (Node* node : sorted_nodes) {
307	    if (IsUntimed(node)) {
308	      completion_time[node] = 0;
309	      continue;
310	    }
311	    int64_t start_time = 0;
312	    for (Node* operand : node->operands()) {
313	      if (IsUntimed(operand)) {
314	        continue;
315	      }
316	      if (schedule.cycle(operand) == schedule.cycle(node)) {
317	        start_time = std::max(start_time, completion_time[operand]);
318	      }
319	    }
320	    XLS_ASSIGN_OR_RETURN(int64_t node_delay,
321	                         delay_estimator.GetOperationDelayInPs(node));
322	    completion_time[node] = start_time + node_delay;
323	    delay_per_stage[schedule.cycle(node)] =
324	        std::max(delay_per_stage[schedule.cycle(node)], completion_time[node]);
325	  }
326	  return delay_per_stage;
327	}
328	
329	absl::Status PrintScheduleInfo(FunctionBase* f,
330	                               const PipelineSchedule& schedule,
331	                               const BddQueryEngine& bdd_query_engine,
332	                               const DelayEstimator& delay_estimator,
333	                               std::optional<int64_t> clock_period_ps) {
334	  int64_t total_flops = 0;
335	  int64_t total_duplicates = 0;
336	  int64_t total_constants = 0;
337	  std::vector<int64_t> flops_per_stage(schedule.length());
338	  std::vector<int64_t> duplicates_per_stage(schedule.length());
339	  std::vector<int64_t> constants_per_stage(schedule.length());
340	  XLS_ASSIGN_OR_RETURN(absl::flat_hash_set<Node*> dead_after_synthesis,
341	                       GetDeadAfterSynthesisNodes(f));
342	  for (int64_t i = 0; i < schedule.length(); ++i) {
343	    absl::flat_hash_map<BddNodeIndex, std::pair<Node*, int64_t>> bdd_nodes;
344	    for (Node* node : schedule.GetLiveOutOfCycle(i)) {
345	      if (!dead_after_synthesis.contains(node) &&
346	          (f->HasImplicitUse(node) ||
347	           absl::c_any_of(node->users(), [&](Node* user) {
348	             return schedule.cycle(user) > i &&
349	                    dead_after_synthesis.contains(user);
350	           }))) {
351	        flops_per_stage[i] += node->GetType()->GetFlatBitCount();
352	      }
353	      if (node->GetType()->IsBits()) {
354	        for (int64_t bit_index = 0; bit_index < node->BitCountOrDie();
355	             ++bit_index) {
356	          TreeBitLocation location(node, bit_index);
357	          if (std::optional<bool> known_value =
358	                  bdd_query_engine.KnownValue(location);
359	              known_value.has_value()) {
360	            VLOG(1) << absl::StreamFormat("%s:%d in stage %d is known %s",
361	                                          node->GetName(), bit_index, i,
362	                                          *known_value ? "zero" : "one");
363	            constants_per_stage[i]++;
364	            total_constants++;
365	          } else if (BddNodeIndex bdd_node =
366	                         *bdd_query_engine.GetBddNode(location);
367	                     bdd_nodes.contains(bdd_node)) {
368	            VLOG(1) << absl::StreamFormat(
369	                "%s:%d in stage %d duplicate of %s:%d", node->GetName(),
370	                bit_index, i, bdd_nodes.at(bdd_node).first->GetName(),
371	                bdd_nodes.at(bdd_node).second);
372	            duplicates_per_stage[i]++;
373	            total_duplicates++;
374	          } else {
375	            bdd_nodes[bdd_node] = {node, bit_index};
376	          }
377	        }
378	      }
379	    }
380	    total_flops += flops_per_stage[i];
381	  }
382	
383	  XLS_ASSIGN_OR_RETURN(std::vector<int64_t> delay_per_stage,
384	                       GetDelayPerStageInPs(f, schedule, delay_estimator));
385	
386	  // TODO(tedhong) 2023-03-06 - Add functionality to report I/O flop count.
387	  std::cout << "Pipeline:\n";
388	  for (int64_t i = 0; i < schedule.length(); ++i) {
389	    std::string stage_str = absl::StrFormat(
390	        "  [Stage %2d] flops: %4d (%4d dups, %4d constant)\n", i,
391	        flops_per_stage[i], duplicates_per_stage[i], constants_per_stage[i]);
392	
393	    // Horizontally offset the information about the logic in the stage from
394	    // the information about stage registers to make it easier to scan the
395	    // information vertically without register and logic info intermixing.
396	    std::cout << std::string(stage_str.size(), ' ');
397	    std::cout << absl::StreamFormat("nodes: %4d, delay: %4dps\n",
398	                                    schedule.nodes_in_cycle(i).size(),
399	                                    delay_per_stage[i]);
400	
401	    if (i + 1 != schedule.length()) {
402	      std::cout << stage_str;
403	    }
404	  }
405	  std::cout << absl::StreamFormat(
406	      "Total pipeline flops: %d (%d dups, %4d constant)\n", total_flops,
407	      total_duplicates, total_constants);
408	
409	  if (clock_period_ps.has_value()) {
410	    int64_t min_slack = std::numeric_limits<int64_t>::max();
411	    for (int64_t stage_delay : delay_per_stage) {
412	      min_slack = std::min(min_slack, *clock_period_ps - stage_delay);
413	    }
414	    std::cout << absl::StreamFormat("Min stage slack: %d\n", min_slack);
415	  }
416	
417	  return absl::OkStatus();
418	}
419	
420	absl::Status PrintScheduleInfo(const PackageSchedule& package_schedule,
421	                               const DelayEstimator& delay_estimator,
422	                               std::optional<int64_t> clock_period_ps) {
423	  if (package_schedule.GetSchedules().size() == 1) {
424	    // With multiple schedules there may be multiple minimum clock periods.
425	    // However, a consumer of the output of this utility expects a single value
426	    // for this metric. The core underlying problem is that we should have a
427	    // single minimum clock period across multiple FunctionBases (procs) rather
428	    // than minimizing on a per-FunctionBase basis.
429	    const PipelineSchedule& schedule =
430	        package_schedule.GetSchedules().begin()->second;
431	    if (schedule.min_clock_period_ps().has_value()) {
432	      std::cout << absl::StreamFormat("Min clock period ps: %d\n",
433	                                      *schedule.min_clock_period_ps());
434	    }
435	  }
436	  for (auto& [function_base, schedule] : package_schedule.GetSchedules()) {
437	    std::cout << "\n\nFunction: " << function_base->name() << "\n";
438	    // NB query engines are associated with a specific function, so we need to
439	    // create a new one for each function.
440	    BddQueryEngine query_engine(BddQueryEngine::kDefaultPathLimit);
441	    XLS_RETURN_IF_ERROR(query_engine.Populate(function_base).status());
442	    XLS_RETURN_IF_ERROR(PrintScheduleInfo(function_base, schedule, query_engine,
443	                                          delay_estimator, clock_period_ps));
444	  }
445	  return absl::OkStatus();
446	}
