459	// Invokes `f` until (approximately) at least`duration_ms` milliseconds have
460	// passed and returns the number of calls per second.
461	absl::StatusOr<float> CountRate(const std::function<void()>& f,
462	                                int64_t duration_ms) {
463	  // To avoid including absl::Now() calls in the time measurement, first
464	  // estimate how many calls it will take for `duration_ms` milliseconds to
465	  // elapse. This is done my running until `duration_ms / 10` milliseconds have
466	  // elapsed with absl::Now() in the loop.
467	  int64_t call_count = 0;
468	  absl::Time start_estimate = absl::Now();
469	  while (DurationToMs(absl::Now() - start_estimate) < duration_ms / 10) {
470	    f();
471	    ++call_count;
472	  }
473	
474	  // Then run 10x the estimated call count to get close to `duration_ms` total
475	  // run time.
476	  absl::Time start_actual = absl::Now();
477	  for (int64_t i = 0; i < call_count * 10; ++i) {
478	    f();
479	  }
480	  int64_t elapsed_ms = DurationToMs(absl::Now() - start_actual);
481	  return elapsed_ms == 0 ? 0.0f : (1000.0 * call_count) / elapsed_ms;
482	}
