484	template <typename ParamNode, typename Rng>
485	std::vector<std::vector<Value>> GetRandomParams(
486	    FunctionBase* function, int64_t input_count,
487	    absl::Span<ParamNode* const> params, Rng& rng_engine) {
488	  std::vector<std::vector<Value>> arg_set(input_count);
489	  for (std::vector<Value>& args : arg_set) {
490	    args.reserve(params.size());
491	    for (Node* param : params) {
492	      args.push_back(RandomValue(param->GetType(), rng_engine));
493	    }
494	  }
495	  return arg_set;
496	}
