498	struct JitArguments {
499	  std::vector<std::vector<std::vector<uint8_t>>> arg_buffers;
500	  std::vector<std::vector<uint8_t*>> arg_pointers;
501	};
502	
503	absl::StatusOr<JitArguments> ConvertToJitArguments(
504	    const std::vector<std::vector<Value>>& arg_set,
505	    absl::Span<Type* const> params, JitRuntime* runtime) {
506	  std::vector<std::vector<std::vector<uint8_t>>> arg_buffers;
507	  std::vector<std::vector<uint8_t*>> arg_pointers;
508	  for (const std::vector<Value>& args : arg_set) {
509	    std::vector<std::vector<uint8_t>> buffers;
510	    std::vector<uint8_t*> pointers;
511	    buffers.reserve(args.size());
512	    pointers.reserve(args.size());
513	    for (int64_t i = 0; i < args.size(); ++i) {
514	      buffers.push_back(
515	          std::vector<uint8_t>(runtime->ShouldAllocateForAlignment(
516	                                   runtime->GetTypeByteSize(params[i]),
517	                                   runtime->GetTypeAlignment(params[i])),
518	                               0));
519	      pointers.push_back(runtime
520	                             ->AsAligned(absl::MakeSpan(buffers.back()),
521	                                         runtime->GetTypeAlignment(params[i]))
522	                             .data());
523	      CHECK_NE(pointers.back(), nullptr);
524	    }
525	    arg_buffers.push_back(std::move(buffers));
526	    arg_pointers.push_back(pointers);
527	    XLS_RETURN_IF_ERROR(runtime->PackArgs(args, params, arg_pointers.back()));
528	  }
529	  return JitArguments{std::move(arg_buffers), std::move(arg_pointers)};
530	}
531	
532	// Run the interpreter/JIT for a fixed amount of time and measure the rate of
533	// calls per second.
534	constexpr int64_t kRunDurationMs = 500;
535	constexpr int64_t kJitRunMultiplier = 1000;
536	
537	template <typename Rng>
538	absl::Status RunFunctionInterpreterAndJit(Function* function,
539	                                          std::string_view description,
540	                                          Rng& rng_engine) {
541	  absl::Time start_jit_compile = absl::Now();
542	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<FunctionJit> jit,
543	                       FunctionJit::Create(function));
544	  std::cout << absl::StreamFormat(
545	      "JIT compile time (%s): %dms\n", description,
546	      DurationToMs(absl::Now() - start_jit_compile));
547	
548	  const int64_t kInputCount = 100;
549	  auto arg_set =
550	      GetRandomParams(function, kInputCount, function->params(), rng_engine);
551	
552	  // To avoid being dominated by xls::Value conversion to native
553	  // format, preconvert the arguments.
554	  XLS_ASSIGN_OR_RETURN(
555	      JitArguments jit_args,
556	      ConvertToJitArguments(arg_set, function->GetType()->parameters(),
557	                            jit->runtime()));
558	  auto [jit_arg_buffers, jit_arg_pointers] = std::move(jit_args);
559	
560	  // The JIT is much faster so run many times.
561	  InterpreterEvents events;
562	  std::vector<uint8_t> result_buffer(jit->runtime()->ShouldAllocateForAlignment(
563	      jit->GetReturnTypeSize(), jit->GetReturnTypeAlignment()));
564	  absl::Span<uint8_t> result_aligned = jit->runtime()->AsAligned(
565	      absl::MakeSpan(result_buffer), jit->GetReturnTypeAlignment());
566	  XLS_ASSIGN_OR_RETURN(
567	      float jit_run_rate,
568	      CountRate(
569	          [&]() -> absl::Status {
570	            for (int64_t i = 0; i < kJitRunMultiplier; ++i) {
571	              for (const std::vector<uint8_t*>& pointers : jit_arg_pointers) {
572	                CHECK_OK(jit->RunWithViews(pointers, result_aligned, &events));
573	              }
574	            }
575	            return absl::OkStatus();
576	          },
577	          kRunDurationMs));
578	  std::cout << absl::StreamFormat(
579	      "JIT run time (%s): %d Kcalls/s\n", description,
580	      static_cast<int64_t>(kInputCount * jit_run_rate));
581	
582	  XLS_ASSIGN_OR_RETURN(
583	      float interpreter_run_rate,
584	      CountRate(
585	          [&]() -> absl::Status {
586	            for (const std::vector<Value>& args : arg_set) {
587	              CHECK_OK(InterpretFunction(function, args).status());
588	            }
589	            return absl::OkStatus();
590	          },
591	          kRunDurationMs));
592	  std::cout << absl::StreamFormat(
593	      "Interpreter run time (%s): %d calls/s\n", description,
594	      static_cast<int64_t>(kInputCount * interpreter_run_rate));
595	  return absl::OkStatus();
596	}
597	
598	template <typename Rng>
599	absl::Status RunBlockInterpreterAndJit(Block* block,
600	                                       std::string_view description,
601	                                       Rng& rng_engine) {
602	  absl::Time start_jit_compile = absl::Now();
603	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<BlockJit> jit, BlockJit::Create(block));
604	  std::cout << absl::StreamFormat(
605	      "JIT compile time (%s): %dms\n", description,
606	      DurationToMs(absl::Now() - start_jit_compile));
607	
608	  const int64_t kInputCount = 100;
609	  std::vector<std::vector<Value>> arg_set =
610	      GetRandomParams(block, kInputCount, block->GetInputPorts(), rng_engine);
611	  std::vector<absl::flat_hash_map<std::string, Value>> port_set;
612	  port_set.reserve(arg_set.size());
613	  absl::c_transform(arg_set, std::back_inserter(port_set),
614	                    [&](const std::vector<Value>& ports) {
615	                      absl::flat_hash_map<std::string, Value> out;
616	                      out.reserve(ports.size());
617	                      for (int i = 0; i < ports.size(); ++i) {
618	                        out[block->GetInputPorts()[i]->name()] = ports[i];
619	                      }
620	                      return out;
621	                    });
622	
623	  // To avoid being dominated by xls::Value conversion to native
624	  // format, preconvert the arguments.
625	  std::vector<Type*> input_types;
626	  input_types.reserve(block->GetInputPorts().size());
627	  absl::c_transform(block->GetInputPorts(), std::back_inserter(input_types),
628	                    [](InputPort* v) { return v->GetType(); });
629	  XLS_ASSIGN_OR_RETURN(
630	      auto jit_args,
631	      ConvertToJitArguments(arg_set, input_types, jit->runtime()));
632	  auto [jit_arg_buffers, jit_arg_pointers] = std::move(jit_args);
633	
634	  // The JIT is much faster so run many times.
635	  auto jit_continuation = jit->NewContinuation(
636	      BlockEvaluator::OutputPortSampleTime::kAtLastPosEdgeClock);
637	  XLS_ASSIGN_OR_RETURN(
638	      float jit_run_rate,
639	      CountRate(
640	          [&]() -> absl::Status {
641	            for (int64_t i = 0; i < kJitRunMultiplier; ++i) {
642	              for (const std::vector<uint8_t*>& pointers : jit_arg_pointers) {
643	                CHECK_OK(jit_continuation->SetInputPorts(pointers));
644	                CHECK_OK(jit->RunOneCycle(*jit_continuation));
645	              }
646	            }
647	            return absl::OkStatus();
648	          },
649	          kRunDurationMs));
650	  std::cout << absl::StreamFormat(
651	      "JIT run time (%s): %d Kcalls/s\n", description,
652	      static_cast<int64_t>(kInputCount * jit_run_rate));
653	
654	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<BlockContinuation> continuation,
655	                       kInterpreterBlockEvaluator.NewContinuation(block));
656	  XLS_ASSIGN_OR_RETURN(
657	      float interpreter_run_rate,
658	      CountRate(
659	          [&]() -> absl::Status {
660	            for (const absl::flat_hash_map<std::string, Value>& ports :
661	                 port_set) {
662	              CHECK_OK(continuation->RunOneCycle(ports));
663	            }
664	            return absl::OkStatus();
665	          },
666	          kRunDurationMs));
667	  std::cout << absl::StreamFormat(
668	      "Interpreter run time (%s): %d calls/s\n", description,
669	      static_cast<int64_t>(kInputCount * interpreter_run_rate));
670	  return absl::OkStatus();
671	}
672	
673	template <typename Rng>
674	absl::Status RunProcInterpreterAndJit(Proc* proc, std::string_view description,
675	                                      Rng& rng_engine) {
676	  absl::Time start_jit_compile = absl::Now();
677	  // Technically the creation cost to get the data layout is amortized over all
678	  // the procs in the elaboration.
679	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<OrcJit> layout_source, OrcJit::Create());
680	  XLS_ASSIGN_OR_RETURN(auto data_layout, layout_source->CreateDataLayout());
681	  XLS_ASSIGN_OR_RETURN(
682	      std::unique_ptr<JitChannelQueueManager> queue_manager,
683	      JitChannelQueueManager::CreateThreadSafe(
684	          proc->package(), std::make_unique<JitRuntime>(data_layout)));
685	  XLS_ASSIGN_OR_RETURN(
686	      std::unique_ptr<ProcJit> jit,
687	      ProcJit::Create(proc, &queue_manager->runtime(), queue_manager.get()));
688	  std::cout << absl::StreamFormat(
689	      "JIT compile time (%s): %dms\n", description,
690	      DurationToMs(absl::Now() - start_jit_compile));
691	  // TODO(meheff): 2022/5/16 Run the proc as well.
692	
693	  return absl::OkStatus();
694	}
695	
696	absl::Status RunInterpreterAndJit(FunctionBase* function_base,
697	                                  std::string_view description) {
698	  std::minstd_rand rng_engine;
699	  if (function_base->IsFunction()) {
700	    Function* function = function_base->AsFunctionOrDie();
701	    return RunFunctionInterpreterAndJit(function, description, rng_engine);
702	  }
703	
704	  if (function_base->IsBlock()) {
705	    Block* block = function_base->AsBlockOrDie();
706	    return RunBlockInterpreterAndJit(block, description, rng_engine);
707	  }
708	
709	  XLS_RET_CHECK(function_base->IsProc());
710	  Proc* proc = function_base->AsProcOrDie();
711	  return RunProcInterpreterAndJit(proc, description, rng_engine);
712	}
