714	absl::Status AnalyzeAndPrintCriticalPath(
715	    FunctionBase* f, std::optional<int64_t> effective_clock_period_ps,
716	    const DelayEstimator& delay_estimator, const AreaEstimator* area_estimator,
717	    const QueryEngine& query_engine, PackageSchedule* package_schedule,
718	    synthesis::Synthesizer* synthesizer) {
719	  XLS_ASSIGN_OR_RETURN(
720	      std::vector<CriticalPathEntry> critical_path,
721	      AnalyzeCriticalPath(f, effective_clock_period_ps, delay_estimator));
722	  synthesis::SynthesizedDelayDiffByStage delay_diff;
723	  if (synthesizer) {
724	    if (package_schedule) {
725	      XLS_ASSIGN_OR_RETURN(
726	          delay_diff, CreateDelayDiffByStage(
727	                          f, package_schedule->GetSchedules().begin()->second,
728	                          delay_estimator, synthesizer));
729	      delay_diff.total_diff.critical_path = std::move(critical_path);
730	    } else {
731	      XLS_ASSIGN_OR_RETURN(
732	          delay_diff.total_diff,
733	          SynthesizeAndGetDelayDiff(f, critical_path, synthesizer));
734	    }
735	  } else {
736	    delay_diff.total_diff.critical_path = std::move(critical_path);
737	  }
738	  XLS_RETURN_IF_ERROR(PrintCriticalPath(f, query_engine, delay_diff));
739	  XLS_RETURN_IF_ERROR(PrintTotalDelay(f, delay_estimator));
740	  if (area_estimator != nullptr) {
741	    XLS_RETURN_IF_ERROR(PrintTotalArea(f, *area_estimator));
742	  }
743	  return absl::OkStatus();
744	}
