746	absl::Status RealMain(std::string_view path) {
747	  VLOG(1) << "Reading contents at path: " << path;
748	  XLS_ASSIGN_OR_RETURN(std::string contents, GetFileContents(path));
749	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<Package> package,
750	                       Parser::ParsePackage(contents));
751	
752	  XLS_ASSIGN_OR_RETURN(CodegenFlagsProto codegen_flags_proto,
753	                       GetCodegenFlags());
754	  if (!codegen_flags_proto.top().empty()) {
755	    XLS_RETURN_IF_ERROR(package->SetTopByName(codegen_flags_proto.top()));
756	  }
757	  XLS_ASSIGN_OR_RETURN(
758	      SchedulingOptionsFlagsProto scheduling_options_flags_proto,
759	      GetSchedulingOptionsFlagsProto());
760	  XLS_ASSIGN_OR_RETURN(
761	      bool delay_model_flag_passed,
762	      IsDelayModelSpecifiedViaFlag(scheduling_options_flags_proto));
763	
764	  if (!package->GetTop().has_value()) {
765	    return absl::InternalError(absl::StrFormat(
766	        "Top entity not set for package: %s.", package->name()));
767	  }
768	  if (absl::GetFlag(FLAGS_run_evaluators)) {
769	    XLS_RETURN_IF_ERROR(
770	        RunInterpreterAndJit(package->GetTop().value(), "unoptimized"));
771	  }
772	
773	  OptimizationPassOptions pass_options;
774	  int64_t convert_array_index_to_select =
775	      absl::GetFlag(FLAGS_convert_array_index_to_select);
776	  pass_options.convert_array_index_to_select =
777	      (convert_array_index_to_select < 0)
778	          ? std::nullopt
779	          : std::make_optional(convert_array_index_to_select);
780	  int64_t split_next_value_selects =
781	      absl::GetFlag(FLAGS_split_next_value_selects);
782	  pass_options.split_next_value_selects =
783	      (split_next_value_selects < 0)
784	          ? std::nullopt
785	          : std::make_optional(split_next_value_selects);
786	  pass_options.use_context_narrowing_analysis =
787	      absl::GetFlag(FLAGS_use_context_narrowing_analysis);
788	  XLS_ASSIGN_OR_RETURN(pass_options.area_estimator,
789	                       GetAreaEstimator(absl::GetFlag(FLAGS_area_model)));
790	  if (!scheduling_options_flags_proto.delay_model().empty()) {
791	    XLS_ASSIGN_OR_RETURN(
792	        pass_options.delay_estimator,
793	        GetDelayEstimator(scheduling_options_flags_proto.delay_model()));
794	  }
795	  XLS_RETURN_IF_ERROR(
796	      RunOptimizationAndPrintStats(package.get(), pass_options));
797	
798	  FunctionBase* f = package->GetTop().value();
799	  BddQueryEngine query_engine(BddQueryEngine::kDefaultPathLimit);
800	  XLS_RETURN_IF_ERROR(query_engine.Populate(f).status());
801	  PrintNodeBreakdown(f);
802	
803	  std::optional<int64_t> effective_clock_period_ps;
804	  if (scheduling_options_flags_proto.has_clock_period_ps() &&
805	      scheduling_options_flags_proto.clock_period_ps() > 0) {
806	    effective_clock_period_ps =
807	        scheduling_options_flags_proto.clock_period_ps();
808	    if (scheduling_options_flags_proto.has_clock_margin_percent()) {
809	      effective_clock_period_ps =
810	          *effective_clock_period_ps -
811	          (*effective_clock_period_ps *
812	               scheduling_options_flags_proto.clock_margin_percent() +
813	           50) /
814	              100;
815	    }
816	  }
817	  const DelayEstimator& defaulted_delay_estimator =
818	      pass_options.delay_estimator ? *pass_options.delay_estimator
819	                                   : GetStandardDelayEstimator();
820	  std::unique_ptr<synthesis::Synthesizer> synthesizer;
821	  if (absl::GetFlag(FLAGS_compare_delay_to_synthesis)) {
822	    synthesis::GrpcSynthesizerParameters parameters(
823	        absl::GetFlag(FLAGS_synthesis_server));
824	    XLS_ASSIGN_OR_RETURN(
825	        synthesizer,
826	        synthesis::GetSynthesizerManagerSingleton().MakeSynthesizer(
827	            parameters.name(), parameters));
828	  }
829	  if (absl::GetFlag(FLAGS_run_evaluators)) {
830	    XLS_RETURN_IF_ERROR(RunInterpreterAndJit(f, "optimized"));
831	  }
832	  const bool benchmark_codegen =
833	      scheduling_options_flags_proto.clock_period_ps() > 0 ||
834	      scheduling_options_flags_proto.pipeline_stages() > 0;
835	  if (!f->IsProc() && !benchmark_codegen) {
836	    XLS_RETURN_IF_ERROR(AnalyzeAndPrintCriticalPath(
837	        f, effective_clock_period_ps, defaulted_delay_estimator,
838	        pass_options.area_estimator, query_engine,
839	        /*package_schedule=*/nullptr, synthesizer.get()));
840	  } else if (benchmark_codegen) {
841	    PackageSchedule package_schedule(package.get());
842	    if (codegen_flags_proto.generator() == GENERATOR_KIND_PIPELINE) {
843	      XLS_ASSIGN_OR_RETURN(SchedulingOptions scheduling_options,
844	                           SetUpSchedulingOptions(
845	                               scheduling_options_flags_proto, package.get()));
846	      XLS_ASSIGN_OR_RETURN(SchedulingResult scheduling_result,
847	                           Schedule(package.get(), scheduling_options,
848	                                    &defaulted_delay_estimator));
849	      XLS_ASSIGN_OR_RETURN(
850	          package_schedule,
851	          PackageSchedule::FromProto(package.get(),
852	                                     scheduling_result.package_schedule));
853	      std::cout << absl::StreamFormat(
854	          "Scheduling time: %dms\n",
855	          PassPipelineDuration(scheduling_result.pass_pipeline_metrics) /
856	              absl::Milliseconds(1));
857	      XLS_RETURN_IF_ERROR(AnalyzeAndPrintCriticalPath(
858	          f, effective_clock_period_ps, defaulted_delay_estimator,
859	          pass_options.area_estimator, query_engine, &package_schedule,
860	          synthesizer.get()));
861	
862	      XLS_RETURN_IF_ERROR(PrintScheduleInfo(
863	          package_schedule, defaulted_delay_estimator,
864	          scheduling_options_flags_proto.has_clock_period_ps()
865	              ? std::make_optional(
866	                    scheduling_options_flags_proto.clock_period_ps())
867	              : std::nullopt));
868	    }
869	
870	    XLS_ASSIGN_OR_RETURN(std::string proc_info,
871	                         f->IsProc() ? ProcInfo(f->AsProcOrDie()) : "");
872	
873	    XLS_ASSIGN_OR_RETURN(
874	        verilog::CodegenResult codegen_result,
875	        Codegen(package.get(), scheduling_options_flags_proto,
876	                codegen_flags_proto, delay_model_flag_passed,
877	                codegen_flags_proto.generator() == GENERATOR_KIND_PIPELINE
878	                    ? &package_schedule
879	                    : nullptr));
880	    std::cout << absl::StreamFormat(
881	        "Codegen time: %dms\n",
882	        PassPipelineDuration(codegen_result.pass_pipeline_metrics) /
883	            absl::Milliseconds(1));
884	
885	    std::cout << absl::StreamFormat(
886	        "Lines of Verilog: %d\n",
887	        std::vector<std::string>(
888	            absl::StrSplit(codegen_result.verilog_text, '\n'))
889	            .size());
890	
891	    // Print out state information for procs.
892	    std::cout << proc_info;
893	
894	    if (absl::GetFlag(FLAGS_run_evaluators)) {
895	      XLS_RETURN_IF_ERROR(
896	          RunInterpreterAndJit(package->blocks()[0].get(), "block"));
897	    }
898	  }
899	
900	  return absl::OkStatus();
901	}
