907	  std::vector<std::string_view> positional_arguments =
908	      xls::InitXls(kUsage, argc, argv);
909	
910	  if (positional_arguments.empty() || positional_arguments[0].empty()) {
911	    LOG(QFATAL) << "Expected path argument with IR: " << argv[0]
912	                << " <ir_path>";
913	  }
914	
915	  return xls::ExitStatus(xls::RealMain(positional_arguments[0]));
916	}
