41	#include "xls/ir/topo_sort.h"
42	
43	namespace xls {
44	
45	const CriticalPathAnnotator::Options CriticalPathAnnotator::kDefaultOptions =
46	    CriticalPathAnnotator::Options();
47	
48	absl::StatusOr<std::vector<CriticalPathEntry>> AnalyzeCriticalPath(
49	    FunctionBase* f, std::optional<int64_t> clock_period_ps,
50	    const DelayEstimator& delay_estimator,
51	    absl::AnyInvocable<bool(Node*)> source_filter,
52	    absl::AnyInvocable<bool(Node*)> sink_filter) {
53	  struct NodeEntry {
54	    Node* node;
55	
56	    // Delay of the node.
57	    int64_t node_delay;
58	
59	    // The delay of the critical path in the graph up to and including this node
60	    // (includes this node's delay).
61	    int64_t critical_path_delay;
62	
63	    // The predecessor on the critical path through this node.
64	    std::optional<Node*> critical_path_predecessor;
65	
66	    // Whether this node was delayed by a cycle boundary.
67	    bool delayed_by_cycle_boundary;
68	  };
69	
70	  // Map from each node to it's corresponding entry.
71	  absl::flat_hash_map<Node*, NodeEntry> node_entries;
72	
73	  // The node with the greatest critical path delay.
74	  std::optional<NodeEntry> latest_entry;
75	
76	  XLS_ASSIGN_OR_RETURN(std::vector<Node*> sorted_nodes, TopoSort(f));
77	  for (Node* node : sorted_nodes) {
78	    if (!source_filter(node) &&
79	        !absl::c_any_of(node->operands(), [&](Node* operand) {
80	          return node_entries.contains(operand);
81	        })) {
82	      // This node is neither a source nor on a path from a source.
83	      continue;
84	    }
85	    NodeEntry& entry = node_entries[node];
86	    entry.node = node;
87	
88	    // The maximum delay from any path up to but not including `node`.
89	    int64_t max_path_delay = 0;
90	    for (Node* operand : node->operands()) {
91	      auto it = node_entries.find(operand);
92	      if (it == node_entries.end()) {
93	        // This operand is neither a source nor on a path from a source.
94	        continue;
95	      }
96	      int64_t operand_path_delay = it->second.critical_path_delay;
97	      if (operand_path_delay >= max_path_delay) {
98	        max_path_delay = operand_path_delay;
99	        entry.critical_path_predecessor = operand;
100	      }
101	    }
102	    XLS_ASSIGN_OR_RETURN(entry.node_delay,
103	                         delay_estimator.GetOperationDelayInPs(node));
104	
105	    // If the dependency straddles a clock boundary we have to make our delay
106	    // start from the clock time.
107	    entry.delayed_by_cycle_boundary = false;
108	    if (clock_period_ps.has_value() &&
109	        (((max_path_delay + entry.node_delay) / clock_period_ps.value()) >
110	         (max_path_delay / clock_period_ps.value()))) {
111	      int64_t new_max_path_delay = RoundDownToNearest(
112	          max_path_delay + entry.node_delay, clock_period_ps.value());
113	      CHECK_GT(new_max_path_delay, max_path_delay);
114	      max_path_delay = new_max_path_delay;
115	      entry.delayed_by_cycle_boundary = true;
116	    }
117	    entry.critical_path_delay = max_path_delay + entry.node_delay;
118	
119	    if (!sink_filter(node)) {
120	      continue;
121	    }
122	    if (!latest_entry.has_value() ||
123	        latest_entry->critical_path_delay <= entry.critical_path_delay) {
124	      latest_entry = entry;
125	    }
126	  }
127	
128	  // `latest_entry` has no value for empty FunctionBases or if the source & sink
129	  // filters removed all nodes.
130	  if (!latest_entry.has_value()) {
131	    return std::vector<CriticalPathEntry>();
132	  }
133	
134	  // Starting with the operation with the longest path delay, walk back up its
135	  // critical path constructing CriticalPathEntry's as we go.
136	  std::vector<CriticalPathEntry> critical_path;
137	  NodeEntry* entry = &(latest_entry.value());
138	  while (true) {
139	    critical_path.push_back(CriticalPathEntry{
140	        .node = entry->node,
141	        .node_delay_ps = entry->node_delay,
142	        .path_delay_ps = entry->critical_path_delay,
143	        .delayed_by_cycle_boundary = entry->delayed_by_cycle_boundary});
144	    if (!entry->critical_path_predecessor.has_value()) {
145	      break;
146	    }
147	    entry = &node_entries.at(entry->critical_path_predecessor.value());
148	  }
149	
150	  return std::move(critical_path);
151	}
152	
153	std::string CriticalPathToString(
154	    absl::Span<const CriticalPathEntry> critical_path,
155	    std::optional<std::function<std::string(Node*)>> extra_info) {
156	  std::string result;
157	  for (const CriticalPathEntry& entry : critical_path) {
158	    absl::StrAppendFormat(&result, " %6dps (+%3dps)%s: %s\n",
159	                          entry.path_delay_ps, entry.node_delay_ps,
160	                          entry.delayed_by_cycle_boundary ? "!" : "",
161	                          entry.node->ToStringWithOperandTypes());
162	    if (extra_info.has_value()) {
163	      absl::StrAppend(&result, extra_info.value()(entry.node));
164	    }
165	  }
166	  return result;
167	}
168	
169	CriticalPathProto CriticalPathToProto(
170	    absl::Span<const CriticalPathEntry> critical_path) {
171	  CriticalPathProto proto;
172	  for (const CriticalPathEntry& entry : critical_path) {
173	    DelayInfoNodeProto* node = proto.add_nodes();
174	    node->set_op(ToOpProto(entry.node->op()));
175	    node->set_node_delay_ps(entry.node_delay_ps);
176	    node->set_total_delay_ps(entry.path_delay_ps);
177	    node->set_id(entry.node->id());
178	    node->set_ir(entry.node->ToStringWithOperandTypes());
179	  }
180	  proto.set_total_delay_ps(critical_path.front().path_delay_ps);
181	  return proto;
182	}
183	
184	absl::StatusOr<CriticalPathAnnotator> CriticalPathAnnotator::Create(
185	    FunctionBase* f, std::optional<int64_t> clock_period_ps,
186	    const DelayEstimator& delay_estimator, Options options,
187	    absl::AnyInvocable<bool(Node*)> source_filter,
188	    absl::AnyInvocable<bool(Node*)> sink_filter) {
189	  XLS_ASSIGN_OR_RETURN(
190	      std::vector<CriticalPathEntry> cp,
191	      AnalyzeCriticalPath(f, clock_period_ps, delay_estimator,
192	                          std::move(source_filter), std::move(sink_filter)));
193	  absl::flat_hash_map<Node*, CriticalPathEntry> entries;
194	  for (const auto& entry : cp) {
195	    entries.emplace(entry.node, entry);
196	  }
197	  return CriticalPathAnnotator(options, std::move(entries));
198	}
199	
200	Annotation CriticalPathAnnotator::NodeAnnotation(Node* node) const {
201	  auto it = critical_path_entries_.find(node);
202	  if (it == critical_path_entries_.end()) {
203	    return Annotation();
204	  }
205	  std::vector<std::string> parts;
206	  parts.push_back(options_.critical_marker);
207	  if (options_.include_node_delay && options_.include_path_delay) {
208	    parts.push_back(absl::StrFormat(
209	        "[%dps (+%dps)%s]", it->second.path_delay_ps, it->second.node_delay_ps,
210	        it->second.delayed_by_cycle_boundary ? "!" : ""));
211	  } else if (options_.include_node_delay) {
212	    parts.push_back(
213	        absl::StrFormat("[+%dps%s]", it->second.node_delay_ps,
214	                        it->second.delayed_by_cycle_boundary ? "!" : ""));
215	  } else if (options_.include_path_delay) {
216	    parts.push_back(
217	        absl::StrFormat("[%dps%s]", it->second.path_delay_ps,
218	                        it->second.delayed_by_cycle_boundary ? "!" : ""));
219	  }
220	  Annotation annotation{.suffix = absl::StrJoin(parts, " ")};
221	  return annotation;
222	}
