16	
17	package xls.estimator_model;
18	
19	// Enum describing the metric that the estimator is estimating. Every estimator
20	// is specific to one metric.
21	enum Metric {
22	  UNSPECIFIED_METRIC = 0;
23	  DELAY_METRIC = 1;
24	  AREA_METRIC = 2;
25	}
26	
27	// Enum describing a specialization of the estimator model of an operation. A
28	// specialization describes a condition under which a metric (such as delay or
29	// area) of the operation is appreciably different then the general case.
30	// For example, a synthesized multiply is generally faster if both operands are
31	// identical and the delay model may include a specialized delay computation for
32	// this case (OPERANDS_IDENTICAL).
33	enum SpecializationKind {
34	  NO_SPECIALIZATION = 0;
35	
36	  // All of the operands of the operation are the same.
37	  // e.g. "square" for mul, "double" for add
38	  OPERANDS_IDENTICAL = 1;
39	
40	  // The operation includes a literal operand.
41	  HAS_LITERAL_OPERAND = 2;
42	}
43	
44	// Describes more specifics of the condition under which the delay/area of the
45	// operation differs. For example, if the kind is HAS_LITERAL_OPERAND, this
46	// might specify that the literal operand must be operand 1.
47	message LiteralOperandDetails {
48	  // If none are specified, then any operand is allowed to be non-literal.
49	  repeated int64 allowed_nonliteral_operand = 1;
50	
51	  // If none are specified, then no specific operand is required to be literal.
52	  repeated int64 required_literal_operand = 2;
53	}
54	
55	// Describes an XLS operation (xls::Node) for the purposes of delay/area
56	// modeling.
57	message Operation {
58	  // XLS Op (e.g., kAdd).
59	  string op = 1;
60	
61	  // Number of bits of the result of the operation. For array-types this is the
62	  // number of bits in each element.
63	  int64 bit_count = 2;
64	
65	  // Operands.
66	  message Operand {
67	    // Number of bits of the operand. For array types this is the number of bits
68	    // in each element.
69	    int64 bit_count = 1;
70	
71	    // If the operand is array-typed, this is the number of elements in the
72	    // array.
73	    int64 element_count = 2;
74	  }
75	  repeated Operand operands = 3;
76	
77	  // The category of specialization of this operation, if any. For example, if
78	  // the operands of the xls::Node represented by this proto are all identical,
79	  // this field would be OPERANDS_IDENTICAL.
80	  SpecializationKind specialization = 4;
81	
82	  message LiteralOperandInstanceDetails {
83	    repeated int64 literal_operand = 1;
84	    repeated int64 nonliteral_operand = 2;
85	  }
86	  LiteralOperandInstanceDetails literal_operand_details = 5;
87	}
88	
89	// Describes a measured data point of the delay and area of an operation.
90	message DataPoint {
91	  Operation operation = 1;
92	
93	  // The measured delay in ps.
94	  int64 delay = 2;
95	
96	  // An optional offset which should be subtracted from the 'delay' value to
97	  // compute the actual delay of the operation. This can be used to account for
98	  // overhead such as clock-to-Q and setup time which may included in the
99	  // measured delay, but is not a component of the delay of the logic of the
100	  // operation. This value is per data point because it may change if underlying
101	  // synthesis rules change and a delay model may be built up over a period of
102	  // time spanning these rules changes.
103	  int64 delay_offset = 3;
104	
105	  // Total area includes both sequential area and combinational area.
106	  double total_area = 4;
107	
108	  double sequential_area = 5;
109	}
110	
111	// Describes an aspect (bit count, number of operands, etc.) of an XLS operation
112	// which may be used as a input in the estimator for the operation.
113	message EstimatorFactor {
114	  enum Source {
115	    INVALID_VARIABLE_SOURCE = 0;
116	
117	    // The bit count of the result of the operation.
118	    RESULT_BIT_COUNT = 1;
119	
120	    // The bit count of a particular operand of the operation. The specific
121	    // operand is indicated by the field operand_number.
122	    OPERAND_BIT_COUNT = 2;
123	
124	    // The total number of operands of the operation.
125	    OPERAND_COUNT = 3;
126	
127	    // The number of element of a particular operand of the operation. The
128	    // operand must be array-typed. The specific operand is indicated by the
129	    // field operand_number.
130	    OPERAND_ELEMENT_COUNT = 4;
131	
132	    // The width of an element number in a particular array-typed operand of the
133	    // operation. The specific operand is indicated by the field operand_number.
134	    OPERAND_ELEMENT_BIT_COUNT = 5;
135	  }
136	  Source source = 1;
137	
138	  // If 'source' is one of the OPERAND_* values then this indicates the operand
139	  // number to use
140	  int64 operand_number = 2;
141	}
142	
143	// Describes a nested mathematical expression combining estimator factors (and
144	// possibly constants). Useful when data for an op cannot be described by a
145	// linear combination of individual factors.
146	message EstimatorExpression {
147	  // The expression is a binary op combining two subexpressions.
148	  enum BinaryOperation {
149	    INVALID = 0;
150	    ADD = 1;
151	    DIVIDE = 2;
152	    MAX = 3;
153	    MIN = 4;
154	    MULTIPLY = 5;
155	    POWER = 6;
156	    SUB = 7;
157	  }
158	
159	  // An expression can be either a BinaryOperation,
160	  // a EstimatorFactor, or an int.
161	  oneof expression_type {
162	    BinaryOperation bin_op = 1;
163	
164	    // The expression is simply an estimator factor.
165	    EstimatorFactor factor = 2;
166	
167	    // The expression is a constant.
168	    int64 constant = 3;
169	  }
170	
171	  // Left and right hand side expressions combined by the BinaryOperation,
172	  // if present.
173	  EstimatorExpression lhs_expression = 4;
174	  EstimatorExpression rhs_expression = 5;
175	}
176	
177	// Settings used for K-fold cross-validation of a regression estimor.
178	// A regression model will fail to build if it does not pass cross validation.
179	message KFoldValidator {
180	  // Note: oneof used here because proto3 does not support optional
181	  // fields without experimental features enabled.
182	  oneof optional_num_cross_validation_folds {
183	    // The number of folds to use for cross validation.
184	    // default = 5
185	    int64 num_cross_validation_folds = 1;
186	  }
187	
188	  oneof optional_max_data_point_error {
189	    // The maximum allowable absolute error for any single data point.
190	    // default = infinity
191	    float max_data_point_error = 2;
192	  }
193	  oneof optional_max_fold_geomean_error {
194	    // max_fold_geomean_error: The maximum allowable geomean absolute error over
195	    // all data points in a given test set.
196	    // default = infinity
197	    float max_fold_geomean_error = 3;
198	  }
199	}
200	
201	// Describes a estimator estimation model which fits a curve to the measured
202	// data points for the operation. The function (curve) includes a constant term
203	// and terms which are linear and logarithm functions of the indicated
204	// expressions. For example, if the expressions are the result bit count and the
205	// operand count then the function for the estimated delay has the form:
206	//
207	//   delay_est = P_0 + P_1 * result_bit_count + P_2 * log2(result_bit_count) +
208	//                     P_3 * operand_count    + P_4 * log2(operand_count)
209	//
210	// Where P_i are learned parameters.
211	message RegressionEstimator {
212	  repeated EstimatorExpression expressions = 1;
213	
214	  // Note: oneof used here because proto3 does not support optional
215	  // fields without experimental features enabled.
216	  oneof optional_kfold_validator {
217	    // K-Fold validation settings.
218	    KFoldValidator kfold_validator = 2;
219	  }
220	}
221	
222	// Similar to RegressionEstimator but includes more terms: x**2, xlogx, x, logx.
223	// For example, if the expressions are u and v, where u is the result bit count,
224	// and v is the operand count, then the area estimator has the form:
225	//   area_est = P_0 + P_1 * u**2 + P_2 * u*log(u) + P_3 * u + P_4 * log(u) +
226	//                    P_5 * v**2 + P_6 * v*log(v) + P_7 * v + P_8 * log(v)
227	//
228	// Where P_i are learned parameters.
229	message AreaRegressionEstimator {
230	  repeated EstimatorExpression expressions = 1;
231	
232	  // Note: oneof used here because proto3 does not support optional
233	  // fields without experimental features enabled.
234	  oneof optional_kfold_validator {
235	    // K-Fold validation settings.
236	    KFoldValidator kfold_validator = 2;
237	  }
238	}
239	
240	// Describes a estimation model in which the measured data points define
241	// bounding boxes in the space of expressions. The estimated delay (or area) for
242	// an operation X is equal to the delay (or area) of the first bounding box
243	// containing the point defined by the operation. For example, suppose the
244	// factors of a bounding box estimator are the result bit count and the operand
245	// count, and the measured data points are:
246	//
247	//   (1) result_bit_count=8, operand_count=3    : 100ps
248	//   (2) result_bit_count=5, operand_count=12   : 150ps
249	//   (3) result_bit_count=10, operand_count=16  : 200ps
250	//
251	// Then the delay of an operation with result_bit_count=5 and operand_count=6
252	// would be 150ps because the point (result_bit_count=5, operand_count=6) is
253	// contained in the bounding box of (result_bit_count=5, operand_count=12).
254	//
255	// The bounding box model is sensitive to the order in which the data points are
256	// listed in the DelayModel proto because the bounding boxes are tested
257	// sequentially and the first match is used.
258	// TODO(meheff): To avoid this undesirable sensitivity, perhaps take the minimum
259	// delay among the enclosing bounding boxes.
260	message BoundingBoxEstimator {
261	  repeated EstimatorFactor factors = 1;
262	}
263	
264	// Estimator which uses logical effort computation to approximate
265	// delay. Specifically, ops with this estimator are handled by the method
266	// DelayEstimator::GetLogicalEffortDelayInPs. Typically only logical operations
267	// (AND, OR, etc) and a small number of other simple operations are handled via
268	// logical effort.
269	message LogicalEffortEstimator {
270	  // The delay of a single inverter in ps.
271	  int64 tau_in_ps = 1;
272	}
273	
274	// Message describing a delay estimation model.
275	message Estimator {
276	  oneof estimator {
277	    // An estimator which returns a fixed value given by 'fixed'.
278	    int64 fixed = 1;
279	
280	    // An estimator which aliases the model of a different op given by
281	    // alias_op. For example, kAdd and kSub have very similar delay
282	    // characteristics so the estimator for kSub may be defined as an alias of
283	    // kAdd by setting 'alias_op' to 'kAdd'.
284	    string alias_op = 2;
285	
286	    // A curve-fitting model.
287	    RegressionEstimator regression = 3;
288	
289	    // A bounding box model.
290	    BoundingBoxEstimator bounding_box = 4;
291	
292	    // A logical effort estimator.
293	    LogicalEffortEstimator logical_effort = 5;
294	
295	    // A curve-fitting model for area.
296	    AreaRegressionEstimator area_regression = 6;
297	  }
298	}
299	
300	// Describes a model for computing the delay/area of a single operation
301	// (e.g. kAdd).
302	message OpModel {
303	  // The xls::Op for this model (e.g., kAdd).
304	  string op = 1;
305	
306	  // The estimator to use to compute the metric.
307	  Estimator estimator = 2;
308	
309	  // Zero or more estimators to use under specialized conditions indicated by
310	  // 'kind'. For example, the OpModel for 'kUMul' may include a specialization
311	  // of kind OPERANDS_IDENTICAL because the delay characteristics are different
312	  // for multiplies if both operands are the same.
313	  message Specialization {
314	    SpecializationKind kind = 1;
315	    Estimator estimator = 2;
316	    message Details {
317	      oneof specialization_details {
318	        LiteralOperandDetails literal_operand_details = 1;
319	      }
320	    }
321	    Details details = 3;
322	  }
323	  repeated Specialization specializations = 3;
324	}
325	
326	// Describes an estimator model used for estimating a specific characteristic of
327	// an XLS operation. For example, this could be use to hold a collection of
328	// estimator models and data points for estimating the area of every op.
329	message EstimatorModel {
330	  // The models for each op.
331	  repeated OpModel op_models = 1;
332	
333	  // Measured delays of XLS operations used as input data for
334	  // RegressionEstimator, AreaRegressionEstimator, and BoundingBoxEstimator.
335	  repeated DataPoint data_points = 2;
336	
337	  // The metric this estimator model is estimating.
338	  Metric metric = 3;
339	}
340	
341	// The op model describes the estimator for each XLS op type supported by this
342	// model.
343	message OpModels {
344	  repeated OpModel op_models = 1;
345	}
346	
347	// Data points gathered from timing characterization or area characterization
348	//   (op, parameterization, specialization, result delay/area)
349	//   used for XLS regression estimators.
350	message DataPoints {
351	  repeated DataPoint data_points = 1;
352	}
353	
354	// For an operand that is an array type, there will be one or more element
355	// counts.
356	// This contains
357	//   * which operand these element counts apply to
358	//   * the element count(s)
359	message OperandElementCounts {
360	  optional int64 operand_number = 1;
361	  repeated int64 element_counts = 2;
362	}
363	
364	// Detailed specification of the operand and result types
365	message Parameterization {
366	  optional int64 result_width = 1;
367	  repeated int64 operand_widths = 2;
368	  // --- anything below is used only with array types ---
369	  repeated int64 result_element_counts = 3;
370	  repeated OperandElementCounts operand_element_counts = 4;
371	}
372	
373	// Specifies the set of sample points for a particular op
374	message OpSamples {
375	  optional string op = 1;
376	  repeated Parameterization samples = 2;
377	  optional SpecializationKind specialization = 3;
378	  optional string attributes = 4;
379	}
380	
381	// Multiple OpSamples messages
382	// There can be multiple op_samples with the same 'op'.
383	message OpSamplesList {
384	  repeated OpSamples op_samples = 1;
385	}
386

